import {getList, add, update, remove} from "@/api/system/usergroup";
import {getDeptTree, getLazyList} from "@/api/system/dept";
import {mapGetters, mapState} from "vuex";
import {iscbaseorgTree} from "@/api/system/user";

export default {
  components: {
  },
  data() {
    return {
      tableHeight: undefined,
      loading: false,
      total: 0,
      showSider: true,
      componentName: 'groupList',
      treeData: [],
      treeProps: { //树组件配置项
        label: 'title',
        isLeaf: 'leaf'
      },
      props: { //树组件配置项
        label: 'title',
        isLeaf: 'leaf'
      },
      form:{},
      searchForm: {
        current: 1,
        size: 20,
      },
      parentId: '',
      deptId:'',
      deptName:'',
      tableData: [{
        hasChildren: true,
        id: "1745022609004736513",
        key: "1745022609004736513",
        parentId: "0",
        title: "国网山东省电力公司",
        value: "1745022609004736513",
        type: 'dept'
      }],
      queryParam: {
          queryKey: 'name',
          queryValue: undefined
      },
      query: {},
      page: {
          pageSize: 10,
          currentPage: 1,
          total: 0
      },

    }
  },
  mounted() {
    this.setPageContentHeight()
    this.getTreeData()
    //记载默认数据
    this.getList()
  },
  computed: {
    ...mapGetters(["permission","userInfo"]),
    permissionList() {
      return {
        addBtn: this.vaildData(this.permission.usergroup_add, false),
        viewBtn: this.vaildData(this.permission.usergroup_view, false),
        delBtn: this.vaildData(this.permission.usergroup_delete, false),
        editBtn: this.vaildData(this.permission.usergroup_edit, false)
      };
    },
    ids() {
      let ids = [];
      this.selectionList.forEach(ele => {
        ids.push(ele.id);
      });
      return ids.join(",");
    }
  },
  methods: {
    getTreeData() {
        getDeptTree(this.form.tenantId).then(res => {
            this.treeData = res.data
        });
    },
    setTableHeight() {
        let pageBody = document.getElementsByClassName('page_body')
        this.tableHeight = pageBody[0].offsetHeight - 55 - 48 - 47 + 'px'
    },
    loadNode(node, resolve) {
        let form = {
            type: '',
            value: '',
        }
        if(node.level === 0) {
            form.type = 'id'
            form.value = "1"
        }else {
            form.type = 'parentId'
            form.value = node.data.id
        }
        iscbaseorgTree(form).then(res => {
            setTimeout(() => {
                this.$refs.scrollbar.update()
            }, 500)
            return resolve(res.data)
        })
    },
    loadNode1(node, resolve) {
      let parentCode =  node.data.id
      if(!parentCode){
        parentCode = '1745022609004736513'
        // userInfo.deptId||
        return resolve(this.tableData)
      }
      // 加载默认
      if (node.data.type === 'dept') {
        //加载下级单位部门
        getLazyList({parentId:parentCode}).then(res => {
          if(res.data){
            //包装tree node格式
            let nodes = res.data;
            nodes.forEach(i => {
              i.hasChildren = true,
              i.key = i.id,
              i.title = i.deptName||'-',
              i.value = i.id,
              i.type = 'dept'
            })
            return resolve(nodes)
          }
        })
        // 加载班组列表
        getList(1,999,{
          deptId: node.data.id
        }).then(res => {
          if(res.data){
            //包装tree node格式
            let nodes = res.data;
            nodes.forEach(i => {
              i.hasChildren = false,
              i.key = i.id,
              i.title = i.groupName||'-',
              i.value = i.id,
              i.type = 'group'
            })
            return resolve(nodes)
          }
        })
      }else {
          return resolve([])
      }
    },
    // eslint-disable-next-line no-unused-vars
    nodeClick(data, node) {
        //id            :            "1770010887220600834"
        //key            :            "1770010887220600834"
        //parentId            :            "1768803691075489793"
        //title            :            "发展建设部"
        //value            :            "1770010887220600834"

      this.searchForm.deptId = data.id
      this.deptId=node.data.id;
      this.query.deptId = data.id
      this.deptName=node.data.title||'';
      //加载班组
      this.getList()
        //加载下级
      this.onLoad(this.page, this.query);
    },
    onLoad(page, params = {}) {
        getList(page.currentPage, page.pageSize, Object.assign(params, this.query)).then(res => {
            const data = res.data;
            this.page.total = data.total;
            this.data = data.records;
        });
    },
    getList() {
      //加载 班组
      this.tableData = []
      this.Loading = true
      getList(1,999,this.searchForm).then(res => {
        this.tableData = res.data
        this.tableData.forEach(i => {i.isEdit = false })
        //this.total = res.data.total
        this.Loading = false
      })
    },
    handleEdit(row) {
      //编辑 行
      this.form = row
      this.tableData.forEach(item => {
        if(item.id == row.id){
          item.isEdit = true;
        }
      })
      row.isEdit = true;
      this.tableData.push({})
      this.tableData.pop()
      this.$refs.table.doLayout()
      this.$forceUpdate();
    },
    handleDelete(id) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。","确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove(id);
        })
        .then(() => {
          this.getList();
          this.$message({
            type: "success",
            message: "操作成功!"
          });
        });
    },
    handleSave(row) {
      //行保存
      if(row.id){
        //修改
        update(row).then(() => {
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.getList()
        }, error => {

        });
      }else{
        //新增
        add(row).then(() => {
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.getList()
        }, error => {

        });
      }
    },
    handleAdd() {
      if(this.deptId){
        this.tableData.push({
          deptId: this.deptId,
          deptName: this.deptName,
          groupCode: '',
          groupName: '',
          isDeleted: 0,
          remark: '',
          sort:9,
          isEdit: true
        })
      }else{
        this.$message({
          type: "warning",
          message: "请选择左侧部门!"
        });
      }
    },
  }
}
